var data = new int[100_000];
for (int i = 0; i < data.Length; i++) data[i] = i;
data[42_000] = -1; data[42_001] = -1;
for (int rep = 0; rep < 50; rep++)
    Cj.Eq(Solution.FirstMatch(data, x => x == -1, 8), 42_000, "lowest index wins, every rep");

// 10M elements, match at index 5, predicate costs ~100ns (SpinWait) - a full scan of all
// workers costs >1s; Stop() must cut it to well under 500ms.
var data = new int[10_000_000];
data[5] = -1;
var sw = System.Diagnostics.Stopwatch.StartNew();
int hit = Solution.FirstMatch(data, x => { if (x == -1) return true; System.Threading.SpinWait.SpinBetween(50); return false; }, 4);
sw.Stop();
Cj.Eq(hit, 5, "finds the early match");
Cj.True(sw.ElapsedMilliseconds < 500, $"early exit required: took {sw.ElapsedMilliseconds}ms (full scan would exceed 1000ms)");
